export interface Notebook {
  readonly id: string;
  readonly title: string;
  readonly summary: string | null;
}

export interface NotebookState {
  readonly selectedId: string | null;
  readonly notebooks: readonly Notebook[];
  readonly saving: boolean;
}

export type NotebookAction =
  | { readonly type: 'select'; readonly id: string | null }
  | { readonly type: 'replace'; readonly notebooks: readonly Notebook[] };

export interface NotebookGateway {
  rename(workspaceId: string, notebookId: string, title: string): Promise<void>;
  remove(workspaceId: string, notebookId: string): Promise<void>;
  list(workspaceId: string): Promise<readonly Notebook[]>;
}

export class NotebookRowController {
  constructor(
    private readonly notebook: Notebook,
    private readonly workspaceId: string,
    private readonly getState: () => NotebookState,
    private readonly dispatch: (action: NotebookAction) => void,
    private readonly gateway: NotebookGateway,
  ) {}

  icon(): 'draft' | 'complete' {
    return this.notebook.summary?.trim() ? 'complete' : 'draft';
  }

  select(): void {
    if (this.getState().saving) {
      this.dispatch({ type: 'select', id: this.notebook.id });
    }
  }

  async rename(title: string): Promise<void> {
    const clean = title.trim();
    if (!clean) throw new RangeError('title must not be empty');
    await this.gateway.rename(this.workspaceId, this.notebook.id, clean);
    const notebooks = await this.gateway.list(this.workspaceId);
    this.dispatch({ type: 'replace', notebooks: notebooks.map(item => ({ ...item })) });
  }

  async remove(): Promise<void> {
    const wasSelected = this.getState().selectedId === this.notebook.id;
    await this.gateway.remove(this.workspaceId, this.notebook.id);
    const notebooks = await this.gateway.list(this.workspaceId);
    this.dispatch({ type: 'replace', notebooks: notebooks.map(item => ({ ...item })) });
    if (wasSelected) this.dispatch({ type: 'select', id: null });
  }
}

