import { Notebook, NotebookState, NotebookGateway, NotebookRowController } from './solution';

function ok(v: unknown, m = 'assertion failed'): asserts v { if (!v) throw new Error(m); }
function equal(a: unknown, b: unknown, m = 'values differ'): void { if (a !== b) throw new Error(`${m}: ${String(a)} !== ${String(b)}`); }
async function rejects(p: Promise<unknown>): Promise<void> { try { await p; } catch { return; } throw new Error('expected rejection'); }

(async () => {
  const notebook: Notebook = { id: 'n1', title: 'Old', summary: '  text  ' };
  let state: NotebookState = { selectedId: 'n1', notebooks: [notebook], saving: false };
  const actions: any[] = []; const calls: string[] = [];
  let listed: any[] = [{ id: 'n1', title: 'New', summary: null }, { id: 'n2', title: 'Two', summary: '' }];
  let failure = false;
  const gateway: NotebookGateway = {
    rename: async (w, id, title) => { calls.push(`rename:${w}:${id}:${title}`); if (failure) throw new Error('rename failed'); },
    remove: async (w, id) => { calls.push(`remove:${w}:${id}`); if (failure) throw new Error('remove failed'); },
    list: async w => { calls.push(`list:${w}`); if (failure) throw new Error('list failed'); return listed; },
  };
  const controller = new NotebookRowController(notebook, 'w1', () => state, a => actions.push(a), gateway);
  equal(controller.icon(), 'complete');
  const draft = new NotebookRowController({ id: 'd', title: 'D', summary: '   ' }, 'w1', () => state, a => actions.push(a), gateway);
  equal(draft.icon(), 'draft');
  controller.select(); equal(actions.length, 1); equal(actions[0].type, 'select'); equal(actions[0].id, 'n1');
  state = { ...state, saving: true }; controller.select(); equal(actions.length, 1); state = { ...state, saving: false };
  try { await controller.rename('   '); throw new Error('expected RangeError'); } catch (e) { ok(e instanceof RangeError); } equal(calls.length, 0);
  actions.length = 0; await controller.rename('  Renamed  ');
  equal(calls.join(','), 'rename:w1:n1:Renamed,list:w1'); equal(actions.length, 1); equal(actions[0].type, 'replace');
  ok(actions[0].notebooks !== listed); ok(actions[0].notebooks[0] !== listed[0]); actions[0].notebooks[0].title = 'mutated'; equal(listed[0].title, 'New'); equal(notebook.title, 'Old');
  calls.length = 0; actions.length = 0; await controller.remove();
  equal(calls.join(','), 'remove:w1:n1,list:w1'); equal(actions.length, 2); equal(actions[0].type, 'replace'); equal(actions[1].type, 'select'); equal(actions[1].id, null);
  state = { ...state, selectedId: 'n2' }; actions.length = 0; calls.length = 0; await controller.remove(); equal(actions.length, 1); equal(actions[0].type, 'replace');
  failure = true; actions.length = 0; calls.length = 0; await rejects(controller.rename('Valid')); equal(actions.length, 0);
})().catch(error => { throw error; });

